div.script:
document.getElementById('isAnonymous').addEventListener('change', function() {
    const section = document.getElementById('reporterSection');
    if (this.checked) {
        section.style.display = 'none';
        document.getElementById('reporterName').value = '';
        document.getElementById('reporterPhone').value = '';
        document.getElementById('reporterEmail').value = '';
    } else {
        section.style.display = 'block';
    }
});

document.getElementById('hasEvidence').addEventListener('change', function() {
    document.getElementById('fileUploadSection').style.display = this.checked ? 'block' : 'none';
});

document.querySelectorAll('.party-type-checkbox[data-other="1"]').forEach(function(checkbox) {
    checkbox.addEventListener('change', function() {
        const section = document.getElementById('partyTypeOtherSection');
        section.style.display = this.checked ? 'block' : 'none';
        if (!this.checked) {
            document.getElementById('partyTypeOtherNote').value = '';
        }
    });
});

(function() {
    const dropzone = document.getElementById('wbDropzone');
    const fileInput = document.getElementById('evidence');
    const chooseBtn = document.getElementById('wbChooseFilesBtn');
    const fileList = document.getElementById('wbFileList');
    if (!dropzone || !fileInput) {
        return;
    }

    // The native file input only ever holds the files from
    // the *last* selection/drop -- keep our own running list so
    // choosing/dropping more files appends instead of replacing,
    // and so a single file can be removed without clearing the
    // rest. The input's real FileList is rebuilt from this array
    // (via DataTransfer) after every change, since that's what
    // actually gets submitted with the form.
    let selectedFiles = [];

    function isDuplicate(file) {
        return selectedFiles.some(function(existing) {
            return existing.name === file.name
                && existing.size === file.size
                && existing.lastModified === file.lastModified;
        });
    }

    function addFiles(fileListLike) {
        Array.from(fileListLike).forEach(function(file) {
            if (!isDuplicate(file)) {
                selectedFiles.push(file);
            }
        });
        syncInput();
        renderFileList();
    }

    function removeFileAt(index) {
        selectedFiles.splice(index, 1);
        syncInput();
        renderFileList();
    }

    function syncInput() {
        const dt = new DataTransfer();
        selectedFiles.forEach(function(file) {
            dt.items.add(file);
        });
        fileInput.files = dt.files;
    }

    function renderFileList() {
        fileList.innerHTML = '';
        selectedFiles.forEach(function(file, index) {
            const item = document.createElement('div');
            item.className = 'wb-file-list-item';
            item.innerHTML = ''
                + '';
            item.querySelector('span').textContent = file.name;
            item.querySelector('.wb-file-list-remove').addEventListener('click', function(ev) {
                ev.preventDefault();
                ev.stopPropagation();
                removeFileAt(index);
            });
            fileList.appendChild(item);
        });
    }

    chooseBtn.addEventListener('click', function() {
        fileInput.click();
    });

    fileInput.addEventListener('change', function() {
        addFiles(fileInput.files);
    });

    const reportForm = document.getElementById('wbReportForm');
    if (reportForm) {
        reportForm.addEventListener('reset', function() {
            selectedFiles = [];
            renderFileList();
        });
    }

    ['dragenter', 'dragover'].forEach(function(evtName) {
        dropzone.addEventListener(evtName, function(ev) {
            ev.preventDefault();
            ev.stopPropagation();
            dropzone.classList.add('wb-dropzone-hover');
        });
    });

    ['dragleave', 'drop'].forEach(function(evtName) {
        dropzone.addEventListener(evtName, function(ev) {
            ev.preventDefault();
            ev.stopPropagation();
            dropzone.classList.remove('wb-dropzone-hover');
        });
    });

    dropzone.addEventListener('drop', function(ev) {
        const dt = ev.dataTransfer;
        if (dt && dt.files && dt.files.length) {
            addFiles(dt.files);
        }
    });
})();
